node <<'NODE'
const fs=require('node:fs');const d=fs.readFileSync('AGENTS.md','utf8');const match=d.match(/## I\. Imperatives — SHALL\n\n~~~json\n([\s\S]*?)\n~~~/);if(!match)throw Error('imperative block missing');const obj=JSON.parse(match[1]);if(obj.rules.length!==33)throw Error('rule count mismatch');if(obj.rules.some(r=>!/^The agent shall\b/.test(r.shall)))throw Error('invalid imperative');if(!d.includes('## II. Procedures — SHOULD'))throw Error('procedures missing');for(let i=1;i<=8;i++)if(!d.includes('### '+i+'. '))throw Error('missing procedure '+i);if(!d.includes('"whatPrompt": <shell_command_with_serialized_extractor_request>'))throw Error('missing template');console.log(JSON.stringify({valid:true,rules:obj.rules.length,procedures:8,bytes:Buffer.byteLength(d)}))
NODE
sha256sum AGENTS.md
encoded="$(base64 -w0 AGENTS.md)"
commit="$(gh api --method PUT repos/BestNameYet/Terminals/contents/AGENTS.md -f message='Add AGENTS.md with separate SHALL imperatives and SHOULD procedures' -f content="$encoded" --jq '.commit.sha')"
echo "published_commit=$commit"
gh api repos/BestNameYet/Terminals/contents/AGENTS.md --jq '.content' | tr -d '\n' | base64 -d > /tmp/terminals-agents-readback
cmp AGENTS.md /tmp/terminals-agents-readback
echo 'REMOTE_READBACK_BYTE_IDENTICAL=yes'
printf 'published_path=AGENTS.md\n'
